import copy
import math


class MemoryArchive:
    def __init__(self, interval, retain_best=True):
        if isinstance(interval, bool) or not isinstance(interval, int):
            raise TypeError("interval must be an integer")
        if interval <= 0:
            raise ValueError("interval must be positive")
        if not isinstance(retain_best, bool):
            raise TypeError("retain_best must be a boolean")
        self.interval = interval
        self.retain_best = retain_best
        self._snapshots = {}
        self._best_score = None

    def record(self, step, state, score, milestone=False):
        if isinstance(step, bool) or not isinstance(step, int):
            raise TypeError("step must be an integer")
        if step < 0:
            raise ValueError("step must be non-negative")
        if not isinstance(state, dict):
            raise TypeError("state must be a dictionary")
        if isinstance(score, bool) or not isinstance(score, (int, float)):
            raise TypeError("score must be numeric")
        if not math.isfinite(score):
            raise ValueError("score must be finite")
        if not isinstance(milestone, bool):
            raise TypeError("milestone must be a boolean")

        periodic = milestone or step % self.interval == 0
        is_best = self.retain_best and (
            self._best_score is None or score >= self._best_score
        )
        labels = []
        planned = []
        if periodic:
            labels.append(f"step-{step}")
        if is_best:
            labels.append(f"best-{step}")

        for label in labels:
            planned.append(
                (
                    label,
                    {
                        "step": step,
                        "score": score,
                        "state": copy.deepcopy(state),
                    },
                )
            )

        for label, snapshot in planned:
            self._snapshots[label] = snapshot
        if is_best:
            self._best_score = score
        return tuple(labels)

    def export(self):
        return copy.deepcopy(self._snapshots)

